import XCTest
@testable import OneThingKit

/// tests/fixtures/outline.json (generated by the C# core's OutlineFixtureTests): the Tasks tree shows the same rows, path,
/// zoom and Open to sets as the web app and Android, for every case.
final class OutlineFixtureTests: XCTestCase {
    private struct Built {
        let board: TaskBoard
        let ids: [String: UUID]
        let keys: [UUID: String]
        let groupIds: [String: UUID]
        let order: [String]
    }

    private func build(_ fixture: [String: Any]) throws -> Built {
        let now = try XCTUnwrap(BoardCodec.parseDate(fixture["now"] as! String))
        let snoozed = try XCTUnwrap(BoardCodec.parseDate(fixture["snoozedUntil"] as! String))
        let board = TaskBoard()
        board.timeZone = TimeZone(identifier: "UTC")!
        let names = fixture["groups"] as! [String]
        for name in names.dropFirst(board.groups.count) { try board.addGroup(name: name, now: now) }
        XCTAssertEqual(board.groups.map(\.name), names)
        let tasks = fixture["tasks"] as! [[String: Any]]
        var ids: [String: UUID] = [:]
        for t in tasks {
            let group = (t["group"] as? String).flatMap { name in board.groups.first { $0.name == name }?.id }
            let item = try board.addTask(NewTask(t["title"] as! String, parentId: (t["parent"] as? String).flatMap { ids[$0] },
                                                 groupId: group, sequential: t["sequential"] as? Bool ?? false), now: now)
            ids[t["key"] as! String] = item.id
        }
        for t in tasks where t["done"] as? Bool == true { try board.complete(ids[t["key"] as! String]!, now: now) }
        for t in tasks where t["snoozed"] as? Bool == true { try board.scheduleNextAction(ids[t["key"] as! String]!, at: snoozed, now: now) }
        for t in tasks where t["archived"] as? Bool == true { try board.archive(ids[t["key"] as! String]!, now: now) }
        var keys = Dictionary(uniqueKeysWithValues: ids.map { ($0.value, $0.key) })
        for group in board.groups { keys[group.id] = group.name }
        return Built(board: board, ids: ids, keys: keys,
                     groupIds: Dictionary(uniqueKeysWithValues: board.groups.map { ($0.name, $0.id) }),
                     order: tasks.map { $0["key"] as! String })
    }

    private func options(_ o: [String: Any], _ b: Built) -> OutlineOptions {
        OutlineOptions(
            groupId: (o["group"] as? String).flatMap { b.groupIds[$0] },
            zoomId: (o["zoom"] as? String).map { b.ids[$0] ?? UUID() },
            show: OutlineShow.parse(o["show"] as? String) ?? .todo,
            query: o["query"] as? String,
            expanded: Set((o["expanded"] as? [String] ?? []).compactMap { b.ids[$0] }),
            closedGroups: Set((o["closedGroups"] as? [String] ?? []).compactMap { b.groupIds[$0] }))
    }

    private func plain(_ rows: [OutlineRow], _ b: Built) -> [[String: Any]] {
        rows.map { r in
            [
                "kind": r.kind == .group ? "group" : "task", "id": b.keys[r.id] ?? "?", "depth": r.depth, "title": r.title,
                "fullTitle": r.fullTitle, "hasChildren": r.hasChildren, "expanded": r.expanded, "done": r.done, "total": r.total,
                "left": r.left, "state": r.state.map { $0.rawValue as Any } ?? NSNull(), "outdent": r.canOutdent,
            ]
        }
    }

    private func check(_ got: Any, _ want: Any?, _ what: String) {
        guard let want else { return XCTFail("\(what): missing in the fixture") }
        if let d = Fixtures.diff(got, want) { XCTFail("\(what): \(d)") }
    }

    private struct Title: Decodable {
        let title: String
        let parent: String?
        let parentShown: String?
        let shown: String
    }

    private struct Titles: Decodable { let titles: [Title] }

    private struct Tags: Decodable {
        struct Case: Decodable {
            let tags: [String]
            let parent: [String]?
            let shown: [String]
        }

        let tags: [Case]
    }

    func testARowShowsOnlyTheTagsItsParentDoesNotAlsoHave() throws {
        let cases = try JSONDecoder().decode(Tags.self, from: Data(contentsOf: Fixtures.root.appendingPathComponent("outline.json"))).tags
        XCTAssertGreaterThanOrEqual(cases.count, 10)
        for t in cases {
            // Compared as UTF-16: Swift's == would call é and e + an accent the same.
            XCTAssertEqual(Outline.shownTags(t.tags, parentTags: t.parent).map { Array($0.utf16) }, t.shown.map { Array($0.utf16) }, "\(t)")
        }
    }

    func testTitlesLeaveOutTheParentsNameTheWayTheFixtureSays() throws {
        // JSONDecoder, not JSONSerialization: that one drops a U+FEFF at the start of a string (one case starts with it).
        let titles = try JSONDecoder().decode(Titles.self, from: Data(contentsOf: Fixtures.root.appendingPathComponent("outline.json"))).titles
        XCTAssertGreaterThanOrEqual(titles.count, 30)
        for t in titles {
            // Compared as UTF-16: Swift's == would call é and e + an accent the same.
            XCTAssertEqual(Array(Outline.shownTitle(t.title, parentTitle: t.parent, parentShownTitle: t.parentShown).utf16), Array(t.shown.utf16), "\(t)")
        }
    }

    func testEveryCaseDrawsTheSameTreeAsTheOtherApps() throws {
        let fixture = try Fixtures.json("outline.json")
        let now = try XCTUnwrap(BoardCodec.parseDate(fixture["now"] as! String))
        let b = try build(fixture)
        let cases = fixture["cases"] as! [[String: Any]]
        XCTAssertGreaterThanOrEqual(cases.count, 27)
        for c in cases {
            let name = c["name"] as! String
            let o = options(c["options"] as! [String: Any], b)
            let zoom = Outline.resolveZoom(b.board, o, now: now)
            XCTAssertEqual(zoom.flatMap { b.keys[$0] }, c["zoom"] as? String, "\(name): zoom")
            XCTAssertEqual(Outline.rememberedZoom(b.board, o).flatMap { b.keys[$0] }, c["remembered"] as? String, "\(name): remembered zoom")
            XCTAssertEqual(Outline.zoomUp(b.board, o, now: now).flatMap { b.keys[$0] }, c["zoomUp"] as? String, "\(name): zoom up")
            check(plain(Outline.rows(b.board, o, now: now), b), c["rows"], "\(name): rows")
            let path: [[String: Any]] = Outline.path(b.board, o, now: now).map { p in
                ["kind": p.kind.rawValue, "id": p.id.flatMap { b.keys[$0] as Any } ?? NSNull(), "title": p.title, "done": p.done, "total": p.total]
            }
            check(path, c["path"], "\(name): path")
            let place = Outline.newTaskPlace(b.board, o, now: now)
            let want = c["newTask"] as! [String: Any]
            XCTAssertEqual(place.parentId.flatMap { b.keys[$0] }, want["parent"] as? String, "\(name): new task parent")
            XCTAssertEqual(b.keys[place.groupId], want["group"] as? String, "\(name): new task group")
            for (level, wanted) in c["openTo"] as? [String: [String: Any]] ?? [:] {
                let open = Outline.openTo(b.board, o, level: try XCTUnwrap(OutlineLevel(rawValue: level)), now: now)
                XCTAssertEqual(b.order.filter { open.expanded.contains(b.ids[$0]!) }, wanted["expanded"] as? [String], "\(name): open to \(level): expanded")
                XCTAssertEqual(b.board.groups.filter { open.closedGroups.contains($0.id) }.map(\.name), wanted["closedGroups"] as? [String],
                               "\(name): open to \(level): closed groups")
                var after = o
                after.expanded = open.expanded
                after.closedGroups = open.closedGroups
                check(plain(Outline.rows(b.board, after, now: now), b), wanted["rows"], "\(name): open to \(level): rows")
            }
        }
    }

    /// Each group's name, then its top-level tasks (archived ones too) and their subtasks, two spaces per level.
    private func tree(_ board: TaskBoard, _ keys: [UUID: String]) -> [String] {
        var lines: [String] = []
        func walk(_ items: [WorkItem], _ depth: Int) {
            for item in items {
                lines.append(String(repeating: "  ", count: depth) + (keys[item.id] ?? "?"))
                walk(item.children, depth + 1)
            }
        }
        for group in board.groups {
            lines.append(group.name)
            walk(board.items.filter { $0.groupId == group.id }, 1)
        }
        return lines
    }

    /// A move the way Tasks plans it (BoardModel and TasksOutlineView call these), nil when it doesn't make it.
    private func plan(_ move: [String: Any], _ o: OutlineOptions, _ b: Built, now: Date) throws -> [BoardMove]? {
        let task = (move["task"] as? String).flatMap { b.ids[$0] }
        switch move["do"] as! String {
        case "indent": return OutlineMoves.indent(b.board, task!, options: o, now: now)
        case "outdent": return OutlineMoves.outdent(b.board, task!, options: o, now: now)
        case "up": return OutlineMoves.step(b.board, task!, by: -1, options: o, now: now)
        case "down": return OutlineMoves.step(b.board, task!, by: 1, options: o, now: now)
        case "drop":
            let zone: OutlineMoves.Zone = ["before": .before, "inside": .inside, "after": .after][move["zone"] as! String]!
            return OutlineMoves.drop(b.board, task!, on: b.ids[move["target"] as! String]!, zone)
        case "dropOnGroup": return OutlineMoves.toTopOfGroup(b.board, task!, groupId: b.groupIds[move["group"] as! String]!)
        case "newTask":
            // As BoardModel.addTask: added, then put before the first task where it goes.
            let place = Outline.newTaskPlace(b.board, o, now: now)
            let first = place.parentId.flatMap { b.board.find($0)?.children.first?.id }
                ?? b.board.items.first { $0.groupId == place.groupId && $0.archivedAt == nil }?.id
            let item = try b.board.addTask(NewTask("New", parentId: place.parentId, groupId: place.parentId == nil ? place.groupId : nil), now: now)
            return first.map { [.reorder(item.id, before: $0)] } ?? []
        default: XCTFail("\(move)"); return nil
        }
    }

    func testEveryMoveEndsAtTheSameTreeAsTheOtherApps() throws {
        let fixture = try Fixtures.json("outline.json")
        let now = try XCTUnwrap(BoardCodec.parseDate(fixture["now"] as! String))
        let start = try build(fixture)
        check(tree(start.board, start.keys), fixture["tree"], "the board the moves start from")
        let moves = fixture["moves"] as! [[String: Any]]
        XCTAssertGreaterThanOrEqual(moves.count, 25)
        for m in moves {
            let name = m["name"] as! String
            let b = try build(fixture)
            let planned = try plan(m["move"] as! [String: Any], options(m["options"] as! [String: Any], b), b, now: now)
            if m["tree"] as? String == "refused" {
                XCTAssertNil(planned, "\(name): refused")
                continue
            }
            let steps = try XCTUnwrap(planned, "\(name): planned")
            for step in steps { try b.board.apply(step, now: now) }
            var keys = b.keys
            if let new = b.board.allItems.first(where: { $0.title == "New" }) { keys[new.id] = "new" }
            check(tree(b.board, keys), m["tree"], "\(name): tree")
        }
    }

    func testSomeoneWhoHadShowFinishedOnStartsAtEverything() {
        XCTAssertEqual(OutlineShow.initial(saved: nil, showDone: true), .all)
        XCTAssertEqual(OutlineShow.initial(saved: nil, showDone: false), .todo)
        XCTAssertEqual(OutlineShow.initial(saved: "", showDone: false), .todo)
        XCTAssertEqual(OutlineShow.initial(saved: "waiting", showDone: true), .waiting, "a choice made since wins")
        XCTAssertEqual(OutlineShow.initial(saved: "nonsense", showDone: false), .todo)
        XCTAssertEqual(OutlineShow.allCases.map(\.label), ["To do", "Can do now", "Waiting", "Everything"])
    }
}
